      initialR: `\\(${TEX.R}_{0}=${fmtFixed(initial.R, 2)}\\)`,
      initialV: `\\(${TEX.V}_{0}=${fmtFixed(initial.V, 2)}\\)`,
      initialH: `\\(${TEX.H}_{0}=${fmtFixed(initial.H, 2)}\\)`,
      initialUc: `\\(${TEX.Uc}_{0}=${fmtFixed(initial.Uc, 2)}\\)`,
