      const cell = cells[index2];
      drawPaperSnapshotFrame(ctx, cell, snapshot, index2);
      const contentTop = cell.top + 26;
      const contentHeight = Math.max(150, cell.height - 30);
      const size = Math.min(cell.width, contentHeight);
